import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { fileURLToPath } from 'node:url';

const here = fileURLToPath(new URL('.', import.meta.url));
// The bundle lands next to the LuCI view that loads it. Both files are build
// output: they are generated by `npm run build` in CI and are not committed.
const outDir = fileURLToPath(new URL('../htdocs/luci-static/resources/airconnect-manager/', import.meta.url));

export default defineConfig({
	plugins: [react()],
	define: { 'process.env.NODE_ENV': JSON.stringify('production') },
	build: {
		outDir,
		// The directory also holds the view's own static files while a build is
		// running, so only ever write the two artifacts below into it.
		emptyOutDir: false,
		cssCodeSplit: false,
		// IIFE, not ESM: the LuCI page loads this with a plain <script> tag, and
		// an ES module would not be able to read the page's `uci`/`rpc`/`poll`
		// globals through a shared scope.
		lib: {
			entry: fileURLToPath(new URL('src/main.jsx', import.meta.url)),
			name: 'AirConnectApp',
			formats: ['iife'],
			fileName: () => 'app.js'
		},
		rollupOptions: {
			output: {
				// Vite emits the extracted stylesheet as style.css; LuCI links it
				// by name, so pin the name here instead of guessing.
				assetFileNames: (asset) => (asset.name === 'style.css' ? 'app.css' : '[name][extname]')
			}
		},
		// Safari 12 / older Android WebViews are common on routers' LAN clients.
		target: 'es2019',
		minify: 'esbuild',
		sourcemap: false
	},
	// No dev server: this is a library build consumed by the router's LuCI page.
	root: here
});
